1709	    async fn close_workers_until(
1710	        &self,
1711	        workers: Vec<(Option<oneshot::Sender<Instant>>, JoinHandle<()>)>,
1712	        deadline: Instant,
1713	    ) {
1714	        let mut pending = JoinSet::new();
1715	        let mut aborts = Vec::with_capacity(workers.len());
1716	        for (stop_tx, worker) in workers {
1717	            if let Some(stop_tx) = stop_tx {
1718	                let _ = stop_tx.send(deadline);
1719	            }
1720	            aborts.push(worker.abort_handle());
1721	            pending.spawn(async move {
1722	                let _ = worker.await;
1723	            });
1724	        }
1725	
1726	        // All workers get the stop signal before any await. Join them concurrently
1727	        // and reserve the final slice to force cancellation and reap their joins.
1728	        let reap_start = deadline - WORKER_REAP_RESERVE;
1729	        while !pending.is_empty() {
1730	            let remaining = reap_start.saturating_duration_since(Instant::now());
1731	            if remaining.is_zero() || timeout(remaining, pending.join_next()).await.is_err() {
1732	                break;
1733	            }
1734	        }
1735	        if pending.is_empty() {
1736	            return;
1737	        }
1738	
1739	        for abort in aborts {
1740	            abort.abort();
1741	        }
1742	        while !pending.is_empty() {
1743	            let remaining = deadline.saturating_duration_since(Instant::now());
1744	            if remaining.is_zero() || timeout(remaining, pending.join_next()).await.is_err() {
1745	                break;
1746	            }
1747	        }
1748	    }
